use std::process;
use test_programs::preview1::open_scratch_directory;

/// Attempt to truncate a file that lives inside a directory which was
/// preopened with read-only file permissions. The runtime must reject the
/// truncation and leave the file contents untouched.
unsafe fn test_readonly_file_truncation(dir_fd: wasip1::Fd) {
    const FILENAME: &str = "test.txt";
    const EXPECTED: &[u8] = b"truncation test file\n";

    // Attempt to open the file with `O_TRUNC`. The file was preopened with
    // read-only permissions, so even though the containing directory allows
    // mutation, truncating the file itself is a write operation that must be
    // rejected by the runtime. Note that we intentionally do *not* request
    // write rights here: this exercises the code path where a guest asks only
    // for truncation without otherwise opening the file for writing.
    let res = wasip1::path_open(
        dir_fd,
        0,
        FILENAME,
        wasip1::OFLAGS_TRUNC,
        wasip1::RIGHTS_FD_READ,
        0,
        0,
    );
    assert!(
        res.is_err(),
        "truncating a read-only file must be rejected by the runtime"
    );
    // In case the runtime incorrectly returned a descriptor, make sure not to
    // leak it. (The assertion above will have already failed in that case.)
    if let Ok(fd) = res {
        wasip1::fd_close(fd).expect("closing the unexpectedly-opened file");
    }

    // Re-open the file read-only and confirm that its contents are unchanged,
    // proving that no truncation took place.
    let file_fd = wasip1::path_open(dir_fd, 0, FILENAME, 0, wasip1::RIGHTS_FD_READ, 0, 0)
        .expect("opening the file for reading");

    let mut buffer = [0u8; 128];
    let nread = wasip1::fd_read(
        file_fd,
        &[wasip1::Iovec {
            buf: buffer.as_mut_ptr(),
            buf_len: buffer.len(),
        }],
    )
    .expect("reading file content");

    assert_eq!(
        &buffer[..nread],
        EXPECTED,
        "file contents must be unchanged after a rejected truncation"
    );

    wasip1::fd_close(file_fd).expect("closing the file");
}

fn main() {
    // Open the read-only preopened directory.
    let dir_fd = match open_scratch_directory("readonly") {
        Ok(dir_fd) => dir_fd,
        Err(err) => {
            eprintln!("{err}");
            process::exit(1)
        }
    };

    unsafe {
        test_readonly_file_truncation(dir_fd);
    }
}
